-- >>> supabase/schemas/00_foundation/010_schemas.sql
-- Foundation · schemas
--
-- `public` is the API contract: only tables a client reads or writes under RLS and the RPCs a
-- client calls by name live there. Every other object lives in a schema PostgREST does not
-- expose, so it cannot be addressed from a device at all (docs/db/target-design.md §2.1).

-- Internal objects: trigger functions, policy helpers, sweeps, queues, FSM kernel.
create schema kc_private;
comment on schema kc_private is 'Internal objects. Not exposed through the API.';

-- Money: payments, ledger, KYC, receipts, provider webhooks.
create schema billing;
comment on schema billing is 'Payments and ledger. Reached only through public RPCs and service-role functions.';

-- Append-only audit trail and account-deletion tombstones.
create schema audit;
comment on schema audit is 'Append-only audit trail. No role may update or delete its rows.';

-- External channels (WhatsApp bot, ingestion). Reserved: tables arrive with that module.
create schema integrations;
comment on schema integrations is 'External channel integrations. Service role only.';

-- Health checks and job telemetry.
create schema ops;
comment on schema ops is 'Operational telemetry. Service role only.';

-- Predicates called from row level security policies. A policy runs as the calling role, so
-- that role needs USAGE here and EXECUTE on each predicate; the schema is still not exposed
-- through the API, so none of them can be called from a device.
create schema kc_access;
comment on schema kc_access is 'Policy predicates. Usable by signed-in members inside policies; not exposed through the API.';

-- >>> supabase/schemas/00_foundation/015_extensions.sql
-- Foundation · extensions
--
-- Created before the privilege file (020) on purpose: that file removes the default EXECUTE
-- grant from functions created after it, and extension functions and operators (PostGIS
-- distance, trigram match) must stay callable with a member's own rights inside queries
-- and policies — identically on Supabase and on a plain PostgreSQL server.
--
-- Installed into the platform's `extensions` schema, never into `public`, so extension
-- functions are not part of the API surface. Types and operator classes are therefore
-- written schema-qualified (`extensions.geography`, `extensions.gin_trgm_ops`).

-- Geography type and spatial indexes for every location in the product.
create extension if not exists postgis with schema extensions;

-- Trigram indexes: substring search over Hebrew names, where word stemming does not help.
create extension if not exists pg_trgm with schema extensions;

-- Lets a GIN index combine a plain equality column with a trigram column, so a name search
-- can be scoped to its parent row in one index (streets of one city).
create extension if not exists btree_gin with schema extensions;

-- >>> supabase/schemas/00_foundation/020_default_privileges.sql
-- Foundation · privileges
--
-- Least privilege by grant, not by RLS alone. Supabase ships `public` with blanket default
-- grants to the API roles; this file removes them, so that from here on an object is
-- reachable only when the file that creates it grants it explicitly.

-- Functions: PostgreSQL grants EXECUTE to PUBLIC on every new function. Remove that default for
-- everything this role creates, in every schema.
alter default privileges for role postgres revoke execute on functions from public;

-- `public`: drop the platform's blanket defaults for the two client roles.
alter default privileges for role postgres in schema public revoke all on tables from anon, authenticated;
alter default privileges for role postgres in schema public revoke all on sequences from anon, authenticated;
alter default privileges for role postgres in schema public revoke all on functions from anon, authenticated;

-- Objects that already exist in `public` on a fresh project lose the same blanket grants.
revoke all on all tables in schema public from anon, authenticated;
revoke all on all sequences in schema public from anon, authenticated;
revoke all on all functions in schema public from public, anon, authenticated;

-- Private schemas: no client role may even resolve a name in them. The service role (Edge
-- Functions, scheduled jobs) gets full access; it bypasses RLS by design.
do $$
declare
  v_schema text;
begin
  foreach v_schema in array array['kc_private', 'billing', 'audit', 'integrations', 'ops'] loop
    execute format('revoke all on schema %I from public, anon, authenticated', v_schema);
    execute format('grant usage on schema %I to service_role', v_schema);
    execute format(
      'alter default privileges for role postgres in schema %I grant all on tables to service_role', v_schema);
    execute format(
      'alter default privileges for role postgres in schema %I grant all on sequences to service_role', v_schema);
    execute format(
      'alter default privileges for role postgres in schema %I grant execute on functions to service_role', v_schema);
  end loop;
end $$;

-- `public` functions stay callable by the service role without a per-function grant.
alter default privileges for role postgres in schema public grant execute on functions to service_role;

-- Policy predicates: signed-in members may resolve names in `kc_access`; each predicate is
-- granted individually by the file that creates it.
revoke all on schema kc_access from public, anon;
grant usage on schema kc_access to authenticated, service_role;
alter default privileges for role postgres in schema kc_access grant execute on functions to service_role;

-- >>> supabase/schemas/00_foundation/030_shared_functions.sql
-- Foundation · shared trigger functions

-- Stamps `updated_at` on every row update. Attached as a BEFORE UPDATE trigger by each table
-- that has the column, so the value never depends on the client clock.
create function kc_private.set_updated_at()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  new.updated_at := now();
  return new;
end;
$$;
comment on function kc_private.set_updated_at() is 'BEFORE UPDATE trigger: sets updated_at to the transaction time.';

-- >>> supabase/schemas/00_foundation/050_fsm_kernel.sql
-- Foundation · lifecycle state machines (engineering decision D-226)
--
-- Every status column in the database moves only along edges declared here. The same edge list
-- is mirrored by FSM_MACHINES in @kc/domain, so SQL, TypeScript and tests share one graph.
-- Each module inserts its own machines next to the table that uses them.

-- The closed set of states of each machine.
create table kc_private.fsm_state (
  machine_id text not null,
  status     text not null,
  primary key (machine_id, status)
);
comment on table kc_private.fsm_state is 'State set of each lifecycle machine. Written only by migrations.';

-- Legal moves. `role = ''` admits every caller; any other value admits only that role.
create table kc_private.fsm_edge (
  machine_id  text not null,
  from_status text not null,
  to_status   text not null,
  role        text not null default '',
  primary key (machine_id, from_status, to_status, role),
  foreign key (machine_id, from_status) references kc_private.fsm_state (machine_id, status),
  foreign key (machine_id, to_status) references kc_private.fsm_state (machine_id, status)
);
comment on table kc_private.fsm_edge is 'Legal moves of each lifecycle machine. Written only by migrations.';
create index fsm_edge_to_status_idx on kc_private.fsm_edge (machine_id, to_status);

alter table kc_private.fsm_state enable row level security;
alter table kc_private.fsm_state force row level security;
alter table kc_private.fsm_edge enable row level security;
alter table kc_private.fsm_edge force row level security;

-- Raises unless `p_from → p_to` is a legal move of `p_machine` for `p_role`.
--   unknown_state        a status that the machine does not have
--   illegal_transition   no edge between the two states
--   forbidden_role       the edge exists, but not for this caller
-- Writing the same status again is a legal no-op.
create function kc_private.fsm_assert_transition(
  p_machine text,
  p_from text,
  p_to text,
  p_role text default null
)
returns void
language plpgsql
stable
set search_path = ''
as $$
declare
  v_edge_roles text[];
begin
  if (select count(*) from kc_private.fsm_state s
       where s.machine_id = p_machine and s.status in (p_from, p_to))
     <> (case when p_from = p_to then 1 else 2 end) then
    raise exception 'unknown_state' using errcode = 'P0001', detail = format('%s: %s → %s', p_machine, p_from, p_to);
  end if;

  if p_from = p_to then
    return;
  end if;

  select array_agg(e.role) into v_edge_roles
    from kc_private.fsm_edge e
   where e.machine_id = p_machine and e.from_status = p_from and e.to_status = p_to;

  if v_edge_roles is null then
    raise exception 'illegal_transition' using errcode = 'P0001', detail = format('%s: %s → %s', p_machine, p_from, p_to);
  end if;

  -- An unrestricted edge admits anyone; a restricted one fails closed on a missing role.
  if '' = any (v_edge_roles) or p_role = any (v_edge_roles) then
    return;
  end if;

  raise exception 'forbidden_role' using errcode = 'P0001', detail = format('%s: %s → %s', p_machine, p_from, p_to);
end;
$$;
comment on function kc_private.fsm_assert_transition(text, text, text, text) is
  'Raises unless the move is a legal edge of the machine for the given role.';

-- Generic guard for a status column. Attach as:
--   before insert or update of <column> on <table>
--   for each row execute function kc_private.fsm_guard_status('<machine>', '<column>')
-- On insert the status must belong to the machine; on update the move must be a legal edge.
-- The acting role is read from the transaction-local setting `kc.fsm_role`, which the RPC
-- performing a role-restricted move sets before it writes.
create function kc_private.fsm_guard_status()
returns trigger
language plpgsql
set search_path = ''
as $$
declare
  v_machine constant text := tg_argv[0];
  v_column constant text := tg_argv[1];
  v_new text := to_jsonb(new) ->> v_column;
  v_old text;
begin
  if tg_op = 'INSERT' then
    -- A move from a state to itself only checks that the state exists.
    perform kc_private.fsm_assert_transition(v_machine, v_new, v_new);
    return new;
  end if;

  v_old := to_jsonb(old) ->> v_column;
  perform kc_private.fsm_assert_transition(
    v_machine, v_old, v_new, nullif(current_setting('kc.fsm_role', true), ''));
  return new;
end;
$$;
comment on function kc_private.fsm_guard_status() is
  'BEFORE INSERT OR UPDATE trigger: enforces the machine named in its first argument on the column named in its second.';

-- >>> supabase/schemas/05_geo/010_cities.sql
-- Geo · cities
--
-- Reference list of localities. Rows are loaded by the seed scripts, never by a client.
-- Every city reference in the product is a foreign key to this table, so a city is never
-- stored as free text.

create table public.cities (
  -- Official locality code (stable across name changes).
  city_id      text primary key,
  name_he      text not null,
  name_en      text not null,
  country_code text not null default 'IL' check (country_code ~ '^[A-Z]{2}$'),
  -- City centre. Also the approximate location of a post that shows its city only.
  location     extensions.geography(Point, 4326)
);
comment on table public.cities is 'Reference list of localities; city centre doubles as the city-level approximate location.';

-- Radius and nearest-city queries.
create index cities_location_gist_idx on public.cities using gist (location);
-- City picker autocomplete: substring match on either name.
create index cities_name_he_trgm_idx on public.cities using gin (name_he extensions.gin_trgm_ops);
create index cities_name_en_trgm_idx on public.cities using gin (lower(name_en) extensions.gin_trgm_ops);

alter table public.cities enable row level security;
alter table public.cities force row level security;

-- Read-only reference data for signed-in members.
create policy cities_select_member on public.cities
  for select to authenticated
  using (true);

grant select on public.cities to authenticated;

-- >>> supabase/schemas/05_geo/020_streets.sql
-- Geo · streets
--
-- Official street list, keyed by city (FR-PROFILE-007 AC1, FR-POST address fields, D-36;
-- an official ride place, D71). Rows are loaded by the reference loader
-- (supabase/seed/reference), never by a client. The source is not filtered (D-36): street code
-- 9000 is the source's "the locality itself" entry and is the only street of many small localities.

create table public.streets (
  city_id   text    not null references public.cities (city_id) on delete cascade,
  -- Official street code. Unique inside its city only, hence the composite key.
  street_id integer not null check (street_id > 0),
  -- The source carries Hebrew names only.
  name_he   text    not null check (btrim(name_he) <> ''),
  -- Street centroid: the approximate location of a post that shows city and street.
  -- Null until a street is geocoded; readers fall back to the city centre.
  location  extensions.geography(Point, 4326),
  -- Also serves the foreign key and "all streets of a city".
  primary key (city_id, street_id)
);
comment on table public.streets is 'Reference list of official streets per city (D-36); optional centroid for street-level approximate locations.';

-- Street picker, after a city is chosen:
--   select street_id, name_he from public.streets
--    where city_id = $1 and name_he ilike '%' || $2 || '%'
--    order by name_he, street_id limit $3;
create index streets_city_name_trgm_idx on public.streets
  using gin (city_id, name_he extensions.gin_trgm_ops);
-- Nearest street to a point (address suggestion from a map pin or the device location).
create index streets_location_gist_idx on public.streets using gist (location);

alter table public.streets enable row level security;
alter table public.streets force row level security;

-- Read-only reference data for signed-in members.
create policy streets_select_member on public.streets
  for select to authenticated
  using (true);

grant select on public.streets to authenticated;

-- >>> supabase/schemas/05_geo/030_road_junctions.sql
-- Geo · road junctions and interchanges
--
-- Named junctions and interchanges of the national road network. With cities and streets they
-- are the official places a ride may use for its origin, destination and meeting points (D71);
-- the catalog and its source were approved in D98. Rows are loaded by the reference loader
-- (supabase/seed/reference), never by a client, and never fetched from the source at runtime.

create table public.road_junctions (
  -- The source's place number; stable across refreshes of the catalog.
  junction_id integer primary key,
  kind        text not null check (kind in ('junction', 'interchange')),
  name_he     text not null check (btrim(name_he) <> ''),
  name_en     text,
  name_ar     text,
  -- The roads that meet there, as the source writes them (for example '2/5').
  roads       text,
  location    extensions.geography(Point, 4326) not null
);
comment on table public.road_junctions is 'Reference list of named road junctions and interchanges: official ride places (D71, D98).';

-- Junctions near a point: meeting-point suggestions and the ride map.
create index road_junctions_location_gist_idx on public.road_junctions using gist (location);
-- Place search by name (public.search_places): substring match on either name.
create index road_junctions_name_he_trgm_idx on public.road_junctions
  using gin (name_he extensions.gin_trgm_ops);
create index road_junctions_name_en_trgm_idx on public.road_junctions
  using gin (lower(name_en) extensions.gin_trgm_ops);

alter table public.road_junctions enable row level security;
alter table public.road_junctions force row level security;

-- Read-only reference data for signed-in members.
create policy road_junctions_select_member on public.road_junctions
  for select to authenticated
  using (true);

grant select on public.road_junctions to authenticated;

-- >>> supabase/schemas/05_geo/040_place_search.sql
-- Geo · place search
--
-- One search over the places a ride can start, end or meet at that are picked by name:
-- cities and road junctions (D71). Streets are not searched here; they are picked inside a
-- chosen city, straight from public.streets. A function rather than two table reads because
-- the picker needs one ranked list across both catalogs with plain latitude / longitude,
-- which a table read of a geography column does not give.

-- Returns at most p_limit places whose Hebrew or English name contains p_query, names that
-- start with it first. Runs with the caller's rights: the tables' own policies apply.
-- junction_kind tells a junction from an interchange so the client can word the label.
create function public.search_places(
  p_query text,
  p_kinds text[] default array['city', 'junction'],
  p_limit integer default 20
)
returns table (
  place_kind    text,
  place_id      text,
  name_he       text,
  name_en       text,
  junction_kind text,
  roads         text,
  city_id       text,
  lat           double precision,
  lng           double precision
)
language plpgsql
stable
set search_path = ''
as $$
declare
  v_query   text := btrim(coalesce(p_query, ''));
  v_pattern text;
begin
  if char_length(v_query) not between 1 and 80 then
    raise exception 'place_query_invalid' using errcode = '22023';
  end if;
  if p_kinds is null or cardinality(p_kinds) = 0 or not (p_kinds <@ array['city', 'junction']) then
    raise exception 'place_kinds_invalid' using errcode = '22023';
  end if;
  if p_limit is null or p_limit not between 1 and 50 then
    raise exception 'place_limit_invalid' using errcode = '22023';
  end if;

  -- The query is matched literally: pattern characters typed by the member are escaped.
  v_pattern := '%' || replace(replace(replace(v_query, '\', '\\'), '%', '\%'), '_', '\_') || '%';

  return query
  select p.place_kind, p.place_id, p.name_he, p.name_en, p.junction_kind, p.roads, p.city_id,
         extensions.st_y(p.location::extensions.geometry),
         extensions.st_x(p.location::extensions.geometry)
    from (
      -- A city without a centre cannot be placed on a route, so it is not a ride place.
      select 'city'::text as place_kind, c.city_id as place_id, c.name_he, c.name_en,
             null::text as junction_kind, null::text as roads, c.city_id, c.location
        from public.cities c
       where 'city' = any (p_kinds)
         and c.location is not null
         and (c.name_he ilike v_pattern or lower(c.name_en) like lower(v_pattern))
      union all
      select 'junction', j.junction_id::text, j.name_he, j.name_en, j.kind, j.roads, null, j.location
        from public.road_junctions j
       where 'junction' = any (p_kinds)
         and (j.name_he ilike v_pattern or lower(j.name_en) like lower(v_pattern))
    ) p
   -- Total order, so equal names always come back in the same sequence.
   order by (p.name_he ilike substr(v_pattern, 2) or lower(p.name_en) like lower(substr(v_pattern, 2))) desc,
            p.name_he, p.place_kind, p.place_id
   limit p_limit;
end;
$$;
comment on function public.search_places(text, text[], integer) is
  'Place picker search over cities and road junctions (D71): at most 50 rows, names starting with the query first.';

grant execute on function public.search_places(text, text[], integer) to authenticated;

-- >>> supabase/schemas/10_identity/010_users.sql
-- Identity · users (public profile)
--
-- One row per member, holding only what other members may see. Private fields, account state
-- and counters live in their own 1:1 tables (user_private, user_account, user_stats), so a
-- row another member can select never contains anything private.

create table public.users (
  -- Same id as the auth account; removing the auth account removes the member.
  id                 uuid primary key references auth.users (id) on delete cascade,
  -- Public, shareable identifier used in profile links.
  share_handle       text not null unique check (share_handle ~ '^[a-z0-9_]{3,30}$'),
  -- Empty until the member completes the first onboarding step.
  display_name       text check (char_length(display_name) between 1 and 50),
  -- Free text; links are rejected so the profile cannot be used for advertising.
  biography          text check (
                       char_length(biography) <= 200
                       and biography !~* '(https?://|www\.|[\w.-]+\.[a-z]{2,})'),
  avatar_url         text,
  city_id            text references public.cities (city_id),
  -- 'Private' hides the member's posts and follower lists from non-followers.
  privacy_mode       text not null default 'Public' check (privacy_mode in ('Public', 'Private')),
  privacy_changed_at timestamptz,
  -- 0 none · 1 phone · 2 identity document · 3 verified badge.
  verification_level smallint not null default 0 check (verification_level between 0 and 3),
  -- BCP 47 tag of the member's interface language.
  preferred_language text check (char_length(preferred_language) between 2 and 35),
  -- Mirror of user_account.status = 'active', maintained by trigger. Kept on this row so the
  -- visibility policy is a plain column test rather than a join on every profile read.
  is_active          boolean not null default false,
  -- Search document over name and handle; `simple` keeps Hebrew tokens unstemmed.
  search_vector      tsvector generated always as (
                       to_tsvector('simple', coalesce(display_name, '') || ' ' || share_handle)) stored,
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now()
);
comment on table public.users is 'Public profile of a member. Contains nothing private.';

-- Member search: whole-word match, then substring match on the display name.
create index users_search_gin_idx on public.users using gin (search_vector) where is_active;
create index users_display_name_trgm_idx on public.users
  using gin (display_name extensions.gin_trgm_ops) where is_active;
-- City filter in member search and city statistics.
create index users_city_idx on public.users (city_id) where is_active;

create trigger users_set_updated_at
  before update on public.users
  for each row execute function kc_private.set_updated_at();

alter table public.users enable row level security;
alter table public.users force row level security;

-- A member sees active profiles, and always their own (whatever its account state).
create policy users_select_active_or_self on public.users
  for select to authenticated
  using (is_active or id = (select auth.uid()));

-- A member edits their own profile; which columns is decided by the grant below.
create policy users_update_self on public.users
  for update to authenticated
  using (id = (select auth.uid()))
  with check (id = (select auth.uid()));

grant select on public.users to authenticated;
-- Handle, privacy mode, verification level and is_active change only through server code.
grant update (display_name, biography, avatar_url, city_id, preferred_language)
  on public.users to authenticated;

-- >>> supabase/schemas/10_identity/020_user_private.sql
-- Identity · user_private (owner-only data)
--
-- Personal details and preferences that only the member may read. Kept out of `users` so
-- that no policy mistake on the public profile can ever expose them.

create table public.user_private (
  user_id                     uuid primary key references public.users (id) on delete cascade,
  -- Contact number shown to a counterparty only through a dedicated RPC.
  contact_phone               text check (char_length(btrim(contact_phone)) between 1 and 20),
  -- Used for age-restricted worlds; written once through an RPC, never directly.
  date_of_birth               date,
  -- Default pickup address, prefilled into new posts. Both parts or neither.
  profile_street              text check (char_length(profile_street) between 1 and 80),
  -- Digits with an optional entrance letter, Latin or Hebrew (U+05D0–U+05EA, written as
  -- escapes because Hebrew text is allowed only in locale files).
  profile_street_number       text check (profile_street_number ~ '^[0-9]+[A-Za-z\u05D0-\u05EA]?$'),
  -- Per-category push settings and quiet hours.
  notification_preferences    jsonb not null default '{}'::jsonb
                                check (jsonb_typeof(notification_preferences) = 'object'),
  -- Whether other members see the "active recently" indicator.
  show_active_status          boolean not null default true,
  -- One-time explainer and nudge dismissals.
  closure_explainer_dismissed boolean not null default false,
  first_post_nudge_dismissed  boolean not null default false,
  -- The member chose to fill in basic details later.
  basic_info_skipped          boolean not null default false,
  updated_at                  timestamptz not null default now(),
  constraint user_private_address_pair_chk
    check ((profile_street is null) = (profile_street_number is null))
);
comment on table public.user_private is 'Personal details and preferences readable only by their owner.';

create trigger user_private_set_updated_at
  before update on public.user_private
  for each row execute function kc_private.set_updated_at();

alter table public.user_private enable row level security;
alter table public.user_private force row level security;

create policy user_private_select_self on public.user_private
  for select to authenticated
  using (user_id = (select auth.uid()));

create policy user_private_update_self on public.user_private
  for update to authenticated
  using (user_id = (select auth.uid()))
  with check (user_id = (select auth.uid()));

grant select on public.user_private to authenticated;
-- date_of_birth is excluded: it is set through an RPC that validates it and forbids changes.
grant update (
  contact_phone, profile_street, profile_street_number, notification_preferences,
  show_active_status, closure_explainer_dismissed, first_post_nudge_dismissed, basic_info_skipped
) on public.user_private to authenticated;

