  ('account_status', 'active', 'suspended_admin'),
  ('account_status', 'active', 'banned'),
  ('account_status', 'active', 'pending_deletion'),
  ('account_status', 'suspended_for_false_reports', 'active'),
  ('account_status', 'suspended_for_false_reports', 'suspended_admin'),
  ('account_status', 'suspended_for_false_reports', 'banned'),
  ('account_status', 'suspended_admin', 'active'),
  ('account_status', 'suspended_admin', 'banned'),
  ('account_status', 'banned', 'active'),
  -- Restoring within the grace period returns to the status held before the request.
  ('account_status', 'pending_deletion', 'active'),
  ('account_status', 'pending_deletion', 'pending_verification'),
  ('onboarding', 'pending_basic_info', 'pending_avatar'),
  -- Deferred basic details (FR-AUTH-015): the member skipped the avatar step.
  ('onboarding', 'pending_basic_info', 'completed'),
  ('onboarding', 'pending_avatar', 'completed');

create table public.user_account (
  user_id                     uuid primary key references public.users (id) on delete cascade,
  status                      text not null default 'pending_verification',
  -- End of a temporary suspension; null for every other status.
  status_until                timestamptz,
  onboarding_state            text not null default 'pending_basic_info',
  -- Moderation counters behind the false-report sanction ladder.
  false_reports_count         integer not null default 0 check (false_reports_count >= 0),
  false_report_sanction_count smallint not null default 0 check (false_report_sanction_count between 0 and 3),
  -- A member barred from the food world cannot post there until this time.
  food_posting_banned_until   timestamptz,
  verified_at                 timestamptz,
  verification_method         text check (verification_method in ('manual', 'document', 'provider', 'org_vouch')),
  -- Account deletion: requested → hidden at once → purged after the grace period.
  deletion_requested_at       timestamptz,
  deletion_purge_at           timestamptz,
  status_before_deletion      text check (status_before_deletion in ('active', 'pending_verification')),
  updated_at                  timestamptz not null default now(),
  -- A purge date exists exactly while the account is pending deletion.
  constraint user_account_pending_deletion_chk
    check ((status = 'pending_deletion') = (deletion_purge_at is not null)),
  constraint user_account_deletion_fields_chk
    check ((deletion_purge_at is null) = (deletion_requested_at is null)
       and (deletion_purge_at is null) = (status_before_deletion is null))
);
comment on table public.user_account is 'Account status, onboarding and deletion state. Written only by server code.';

-- Daily purge job: accounts whose grace period has ended.
create index user_account_purge_due_idx on public.user_account (deletion_purge_at)
  where deletion_purge_at is not null;
-- Daily job that lifts expired suspensions.
create index user_account_status_until_idx on public.user_account (status_until)
  where status_until is not null;

create trigger user_account_status_fsm
  before insert or update of status on public.user_account
  for each row execute function kc_private.fsm_guard_status('account_status', 'status');

create trigger user_account_onboarding_fsm
  before insert or update of onboarding_state on public.user_account
  for each row execute function kc_private.fsm_guard_status('onboarding', 'onboarding_state');

create trigger user_account_set_updated_at
  before update on public.user_account
  for each row execute function kc_private.set_updated_at();

-- Keeps users.is_active equal to (status = 'active'), so profile visibility follows the
-- account state in the same transaction that changes it.
create function kc_private.user_account_sync_is_active()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  update public.users u
     set is_active = (new.status = 'active')
   where u.id = new.user_id
     and u.is_active is distinct from (new.status = 'active');
  return null;
end;
$$;

create trigger user_account_sync_is_active
  after insert or update of status on public.user_account
  for each row execute function kc_private.user_account_sync_is_active();

alter table public.user_account enable row level security;
alter table public.user_account force row level security;

create policy user_account_select_self on public.user_account
  for select to authenticated
  using (user_id = (select auth.uid()));

grant select on public.user_account to authenticated;

-- >>> supabase/schemas/10_identity/040_user_stats.sql
-- Identity · user_stats (denormalized counters)
--
-- Counters shown on a profile. They live apart from `users` so that a follow, a reaction or a
-- new post never rewrites the profile row. Maintained by triggers in the modules that own the
-- counted rows; a nightly job recomputes them and records any drift.

create table public.user_stats (
  user_id                    uuid primary key references public.users (id) on delete cascade,
  followers_count            integer not null default 0 check (followers_count >= 0),
  following_count            integer not null default 0 check (following_count >= 0),
  items_given_count          integer not null default 0 check (items_given_count >= 0),
  items_received_count       integer not null default 0 check (items_received_count >= 0),
  -- Open posts by visibility: a viewer is shown the sum they are allowed to see.
  open_posts_public          integer not null default 0 check (open_posts_public >= 0),
  open_posts_followers_only  integer not null default 0 check (open_posts_followers_only >= 0),
  open_posts_only_me         integer not null default 0 check (open_posts_only_me >= 0),
  posts_created_total        integer not null default 0 check (posts_created_total >= 0),
  karma_points               integer not null default 0 check (karma_points >= 0),
  volunteer_hours_total      numeric(10, 2) not null default 0 check (volunteer_hours_total >= 0),
  updated_at                 timestamptz not null default now()
);
comment on table public.user_stats is 'Profile counters, maintained by triggers and reconciled nightly.';

create trigger user_stats_set_updated_at
  before update on public.user_stats
  for each row execute function kc_private.set_updated_at();

alter table public.user_stats enable row level security;
alter table public.user_stats force row level security;

-- Counters are visible exactly when the profile is: the subquery runs under the caller's
-- own access to `users`, so it inherits that table's policy.
create policy user_stats_select_visible_profile on public.user_stats
  for select to authenticated
  using (exists (select 1 from public.users u where u.id = user_stats.user_id));

-- Column grant: the private "only me" count is left out; its owner reads it through an RPC.
grant select (
  user_id, followers_count, following_count, items_given_count, items_received_count,
  open_posts_public, open_posts_followers_only, posts_created_total, karma_points,
  volunteer_hours_total, updated_at
) on public.user_stats to authenticated;

-- >>> supabase/schemas/10_identity/050_auth_user_triggers.sql
-- Identity · auth account → member rows
--
-- The auth service owns sign-up. These triggers on `auth.users` create the member's four rows
-- in the same transaction as the auth account, and activate the member once a contact
-- channel is confirmed. They are SECURITY DEFINER because the auth service's role has no
-- access to the product tables.

-- True when the auth account has proven a contact channel: Google and Apple accounts are
-- verified by the provider; email and phone accounts once their confirmation arrived.
create function kc_private.auth_user_is_verified(p_auth_user auth.users)
returns boolean
language sql
immutable
set search_path = ''
as $$
  select coalesce(p_auth_user.raw_app_meta_data ->> 'provider', 'email') in ('google', 'apple')
      or p_auth_user.email_confirmed_at is not null
      or p_auth_user.phone_confirmed_at is not null;
$$;

-- Returns a share handle no member holds yet: `u_` plus 12 random hex characters. The
-- handle is random rather than derived from the account id, because a prefix of the id is
-- not unique at scale and a collision would fail the sign-up.
create function kc_private.generate_share_handle()
returns text
language plpgsql
volatile
set search_path = ''
as $$
declare
  v_handle text;
begin
  loop
    v_handle := 'u_' || substr(replace(gen_random_uuid()::text, '-', ''), 1, 12);
    exit when not exists (select 1 from public.users u where u.share_handle = v_handle);
  end loop;
  return v_handle;
end;
$$;

-- Creates the profile, private, account and counter rows of a new member.
create function kc_private.handle_new_auth_user()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_meta constant jsonb := coalesce(new.raw_user_meta_data, '{}'::jsonb);
  -- Name offered by the identity provider, else the local part of the email address.
  v_display_name constant text := left(
    coalesce(
      nullif(btrim(coalesce(v_meta ->> 'full_name', v_meta ->> 'name')), ''),
      nullif(split_part(coalesce(new.email, ''), '@', 1), '')),
    50);
begin
  insert into public.users (id, share_handle, display_name, avatar_url)
  values (
    new.id,
    kc_private.generate_share_handle(),
    v_display_name,
    nullif(coalesce(v_meta ->> 'avatar_url', v_meta ->> 'picture'), ''));

  insert into public.user_private (user_id) values (new.id);
  insert into public.user_stats (user_id) values (new.id);
  insert into public.user_account (user_id, status)
  values (
    new.id,
    case when kc_private.auth_user_is_verified(new) then 'active' else 'pending_verification' end);

  return new;
end;
$$;
comment on function kc_private.handle_new_auth_user() is
  'AFTER INSERT on auth.users: creates the member rows; verified accounts start active.';

create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function kc_private.handle_new_auth_user();

-- Activates a member waiting for verification when their email or phone is confirmed.
-- Any other status is left alone: a suspension or a deletion request outranks verification.
create function kc_private.handle_auth_user_verified()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if kc_private.auth_user_is_verified(new) then
    update public.user_account a
       set status = 'active'
     where a.user_id = new.id
       and a.status = 'pending_verification';
  end if;
  return new;
end;
$$;
comment on function kc_private.handle_auth_user_verified() is
  'AFTER UPDATE on auth.users: pending_verification → active once a contact channel is confirmed.';

create trigger on_auth_user_verified
  after update of email_confirmed_at, phone_confirmed_at on auth.users
  for each row execute function kc_private.handle_auth_user_verified();

-- >>> supabase/schemas/15_social_graph/010_follows.sql
-- Social graph · follows
--
-- One row per "follower follows followed". A private profile is followed through an approved
-- request, so an edge is created only by server code; removing an edge (unfollow, or removing
-- a follower) is a plain delete by either party (FR-FOLLOW-002, FR-FOLLOW-009).

create table public.follows (
  follower_id uuid not null references public.users (id) on delete cascade,
  followed_id uuid not null references public.users (id) on delete cascade,
  created_at  timestamptz not null default now(),
  primary key (follower_id, followed_id),
  constraint follows_not_self_chk check (follower_id <> followed_id)
);
comment on table public.follows is 'Follow edges. Created by server code, deleted by either party.';

-- Followers list of a profile, newest first (keyset on created_at, follower_id).
create index follows_followed_recent_idx on public.follows (followed_id, created_at desc, follower_id);
-- Following list of a profile, newest first; also serves the feed's "people I follow" lookup.
create index follows_follower_recent_idx on public.follows (follower_id, created_at desc, followed_id);

-- Keeps the two profile counters in step with the edge, in the same transaction
-- (FR-FOLLOW-001 AC2). Runs with definer rights because counters are not client-writable.
create function kc_private.follows_sync_counters()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_delta constant integer := case tg_op when 'INSERT' then 1 else -1 end;
  v_edge constant public.follows := case tg_op when 'INSERT' then new else old end;
begin
  update public.user_stats s
     set followers_count = greatest(s.followers_count + v_delta, 0)
   where s.user_id = v_edge.followed_id;
  update public.user_stats s
     set following_count = greatest(s.following_count + v_delta, 0)
   where s.user_id = v_edge.follower_id;
  return null;
end;
$$;

create trigger follows_sync_counters
  after insert or delete on public.follows
  for each row execute function kc_private.follows_sync_counters();

alter table public.follows enable row level security;
alter table public.follows force row level security;

-- Followers and following lists of any member are visible to every signed-in member,
-- whatever the privacy mode (FR-PROFILE-010 AC1). A profile hidden from the viewer drops out
-- when the list is joined to `users`.
create policy follows_select_member on public.follows
  for select to authenticated
  using (true);

-- Unfollow, or remove one of my followers.
create policy follows_delete_party on public.follows
  for delete to authenticated
  using ((select auth.uid()) in (follower_id, followed_id));

grant select, delete on public.follows to authenticated;

-- >>> supabase/schemas/15_social_graph/020_blocks.sql
-- Social graph · blocks
--
-- A block hides two members from each other in both directions. Only the blocker can see or
-- remove the row: the blocked member is never told who blocked them.

create table public.blocks (
  blocker_id uuid not null references public.users (id) on delete cascade,
  blocked_id uuid not null references public.users (id) on delete cascade,
  created_at timestamptz not null default now(),
  primary key (blocker_id, blocked_id),
  constraint blocks_not_self_chk check (blocker_id <> blocked_id)
);
comment on table public.blocks is 'Blocks between members. Visible to the blocker only; effective in both directions.';

-- Reverse lookup: "has this member blocked me?" in the bilateral predicate below.
create index blocks_blocked_idx on public.blocks (blocked_id, blocker_id);

-- True when either member has blocked the other. Definer rights are required because a
-- member cannot read the other side's block row. Used by policies on every table that must
-- hide blocked counterparts.
create function kc_access.is_blocked_between(p_user_a uuid, p_user_b uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
      from public.blocks b
     where (b.blocker_id = p_user_a and b.blocked_id = p_user_b)
        or (b.blocker_id = p_user_b and b.blocked_id = p_user_a));
$$;
comment on function kc_access.is_blocked_between(uuid, uuid) is
  'Policy predicate: a block exists between the two members, in either direction.';
grant execute on function kc_access.is_blocked_between(uuid, uuid) to authenticated;

-- Blocking ends any follow relation between the two members, in both directions.
create function kc_private.blocks_remove_follows()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  delete from public.follows f
   where (f.follower_id = new.blocker_id and f.followed_id = new.blocked_id)
      or (f.follower_id = new.blocked_id and f.followed_id = new.blocker_id);
  return null;
end;
$$;

create trigger blocks_remove_follows
  after insert on public.blocks
  for each row execute function kc_private.blocks_remove_follows();

alter table public.blocks enable row level security;
alter table public.blocks force row level security;

create policy blocks_select_own on public.blocks
  for select to authenticated
  using (blocker_id = (select auth.uid()));

create policy blocks_insert_own on public.blocks
  for insert to authenticated
  with check (blocker_id = (select auth.uid()));

create policy blocks_delete_own on public.blocks
  for delete to authenticated
  using (blocker_id = (select auth.uid()));

grant select, insert, delete on public.blocks to authenticated;

-- Blocked counterparts disappear from each other. Restrictive, so it narrows whatever the
-- permissive profile policies allow; a member's own row is never affected (no self-block).
create policy users_hide_blocked on public.users
  as restrictive
  for select to authenticated
  using (not kc_access.is_blocked_between((select auth.uid()), id));
